// index.js
import React from 'react';
import ReactDOM from 'react-dom';
import 'carbon-components/css/carbon-components.min.css';
import {
  DataTable,
  Table,
  TableHead,
  TableRow,
  TableHeader,
  TableBody,
  TableCell,
} from 'carbon-components-react';

const headers = [
  { key: 'name', header: 'Name' },
  { key: 'status', header: 'Status' },
];

const rows = [
  { id: 'a', name: 'Load balancer 1', status: 'Disabled' },
  { id: 'b', name: 'Load balancer 2', status: 'Starting' },
  { id: 'c', name: 'Load balancer 3', status: 'Active' },
];

function App() {
  return (
    <div style={{ padding: '1rem' }}>
      <h2>Attempt MD Row Height Variant (40px) – Not Supported Today</h2>
      <DataTable rows={rows} headers={headers}>
        {({ rows, headers, getTableProps, getHeaderProps, getRowProps }) => (
          <Table {...getTableProps()}>
            <TableHead>
              <TableRow>
                {headers.map(header => (
                  <TableHeader {...getHeaderProps({ header })} key={header.key}>
                    {header.header}
                  </TableHeader>
                ))}
              </TableRow>
            </TableHead>
            <TableBody>
              {rows.map(row => (
                <TableRow {...getRowProps({ row })} key={row.id}>
                  {row.cells.map(cell => (
                    <TableCell key={cell.id}>{cell.value}</TableCell>
                  ))}
                </TableRow>
              ))}
            </TableBody>
          </Table>
        )}
      </DataTable>
      {/*
        If you attempt to pass a `size="md"` prop here, or apply a
        custom CSS class that sets `height: 2.5rem` on the rows, you will
        find that the default DataTable CSS always uses its existing
        values (3rem for headers / 2rem for rows) instead of 2.5rem.
      */}
    </div>
  );
}

ReactDOM.render(<App />, document.getElementById('root'));
